package org.humanjourney.core.mapfeature;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.humanjourney.core.geography.*;
import org.humanjourney.core.geography.client.GeographyClientConfig;
import org.humanjourney.core.geography.map.client.BoundaryControlLayout;
import org.humanjourney.core.mapfeature.client.FeatureMode;
import com.electronwill.nightconfig.core.CommentedConfig;
class FeatureLocationHudTest {
 static final String DIM=FeatureModelTest.DIM;
 static final GeographyContext MACRO=new GeographyContext("macro","Macro Label","","");
 static final GeographyContext LOCAL=new GeographyContext("macro","Macro Label","local","Local Label");
 static ClientFeatureState.Snapshot known(Set<String> ids,String... json){var projected=FeatureCatalog.project(FeatureModelTest.catalog(json),ids);return new ClientFeatureState.Snapshot(null,projected,new FeatureIndex(projected.values()));}
 static HudPresentation hud(ClientFeatureState.Snapshot s,GeographyContext geo,double x,double z){return FeatureLocationHud.resolve(true,geo,s,DIM,x,z);}
 static String sea(){return FeatureModelTest.polygon("sea",10);}
 @Test void discoveredSeaShowsLabelAndMacroWithoutType(){assertEquals(new HudPresentation("Label sea","Macro Label"),hud(known(Set.of("sea"),sea()),MACRO,20,20));}
 @Test void localIsMostSpecificSecondary(){assertEquals(new HudPresentation("Label sea","Local Label"),hud(known(Set.of("sea"),sea()),LOCAL,20,20));}
 @Test void undiscoveredHigherPriorityGeometryAndLabelNeverEnterClientHud(){var s=known(Set.of("sea"),sea(),FeatureModelTest.polygon("secret",99));assertEquals(Set.of("sea"),s.features().keySet());assertEquals("Label sea",hud(s,LOCAL,20,20).primary());var empty=known(Set.of(),sea());assertEquals(HudPresentation.of(true,LOCAL),hud(empty,LOCAL,20,20));}
 @Test void holeInteriorAndBoundaryReturnExactLandHud(){var s=known(Set.of("sea"),GeometryV2Test.polygon("sea",GeometryV2Test.OUTER,"["+GeometryV2Test.HOLE+"]",10));for(double x:List.of(50D,75D,100D))assertEquals(HudPresentation.of(true,LOCAL),hud(s,LOCAL,x,75));assertEquals("Label sea",hud(s,LOCAL,49,75).primary());}
 @Test void higherPriorityStraitWinsBroaderSea(){var strait=FeatureModelTest.polygon("strait",30).replace("\"sea\"","\"strait\"");var s=known(Set.of("sea","strait"),sea(),strait);assertEquals("Label strait",hud(s,MACRO,20,20).primary());}
 @Test void eitherMultipartComponentResolvesButGapDoesNot(){var s=known(Set.of("multi"),GeometryV2Test.multipart("multi"));assertEquals("Label multi",hud(s,MACRO,-150,150).primary());assertEquals("Label multi",hud(s,MACRO,150,150).primary());assertEquals(HudPresentation.of(true,MACRO),hud(s,MACRO,-50,150));}
 @Test void noMatchPreservesAllPreviousPresentationVariantsExactly(){var s=known(Set.of("sea"),sea());for(var geo:List.of(LOCAL,MACRO,GeographyContext.EMPTY,new GeographyContext("","","local","Local Label")))assertEquals(HudPresentation.of(true,geo),hud(s,geo,500,500));}
 @Test void riverUsesTwoWorldBlocksRegardlessOfDiscoveryRadius(){assertEquals(2.0,FeatureLocationHud.POLYLINE_TOLERANCE_BLOCKS);for(int radius:List.of(1,8,64)){String json=FeatureModelTest.line("river",1).replace("\"geometry\":","\"discovery_radius\":"+radius+",\"geometry\":");var s=known(Set.of("river"),json);assertEquals("Label river",hud(s,MACRO,50,52).primary());assertEquals("Label river",hud(s,MACRO,50,48).primary());assertEquals(HudPresentation.of(true,MACRO),hud(s,MACRO,50,52.001));}}
 @Test void polygonContainmentDoesNotBorrowRiverOrDiscoveryTolerance(){var s=known(Set.of("sea"),sea());assertEquals("Label sea",hud(s,MACRO,0,20).primary());assertEquals(HudPresentation.of(true,MACRO),hud(s,MACRO,-.01,20));}
 @Test void featureWithoutMacroOrLocalStillShowsOneLine(){assertEquals(new HudPresentation("Label sea",""),hud(known(Set.of("sea"),sea()),GeographyContext.EMPTY,20,20));}
 @Test void nonParticipantNeverShowsFeatureEvenWithOldSnapshot(){var s=known(Set.of("sea"),sea());assertFalse(FeatureLocationHud.resolve(false,LOCAL,s,DIM,20,20).visible());}
 @Test void ambiguousPriorityRetainsNormalGeography(){var s=known(Set.of("sea","other"),sea(),FeatureModelTest.polygon("other",10));assertEquals(HudPresentation.of(true,LOCAL),hud(s,LOCAL,20,20));}
 @Test void wrongDimensionAndInvalidPositionFailClosed(){var s=known(Set.of("sea"),sea());assertEquals(HudPresentation.of(true,LOCAL),FeatureLocationHud.resolve(true,LOCAL,s,"minecraft:the_nether",20,20));assertEquals(HudPresentation.of(true,LOCAL),hud(s,LOCAL,Double.NaN,20));}
 @Test void completedClientSnapshotsDriveLocationAndClearWithoutDiscoveryMutation(){var ledger=new FeatureDiscovery();ledger.mark("sea");var before=ledger.snapshot();var data=FeatureModelTest.catalog(sea());var mirror=new ClientFeatureState();assertEquals(HudPresentation.of(true,MACRO),hud(mirror.snapshot(),MACRO,20,20));var session=UUID.randomUUID();for(var f:FeaturePackets.frames(new FeaturePackets.Header(session,1,1,1),FeaturePackets.Mode.FULL,0,FeatureCatalog.project(data,before.ids()).values(),List.of()))mirror.accept(f);assertEquals("Label sea",hud(mirror.snapshot(),MACRO,20,20).primary());mirror.accept(new FeaturePackets.Frame(new FeaturePackets.Header(session,2,1,1),FeaturePackets.Mode.CLEAR,0,0,1,List.of(),List.of(),null));assertEquals(HudPresentation.of(true,MACRO),hud(mirror.snapshot(),MACRO,20,20));assertEquals(before,ledger.snapshot());}
 @Test void fullscreenOffAndDisabledDrawingDoNotAffectLocation(){var config=CommentedConfig.inMemory();GeographyClientConfig.SPEC.setConfig(config);try{GeographyClientConfig.FEATURE_MODE.set(FeatureMode.OFF.id());GeographyClientConfig.FEATURES_ENABLED.set(false);assertEquals("Label sea",hud(known(Set.of("sea"),sea()),MACRO,20,20).primary());}finally{GeographyClientConfig.SPEC.setConfig(null);}}
 @Test void directRiverRetainsExistingSelectionRule(){var s=known(Set.of("sea","river"),sea(),FeatureModelTest.line("river",-100));assertEquals("Label river",hud(s,MACRO,50,51).primary());assertEquals("Label sea",hud(s,MACRO,50,53).primary());}
 @Test void renderUsesPlayerPositionAndMirrorWithoutModeOrXaeroDependency()throws Exception{var root=Path.of(System.getProperty("humanjourney.projectDir"));String render=Files.readString(root.resolve("src/main/java/org/humanjourney/core/geography/client/GeographyHud.java"));assertTrue(render.contains("FeatureLocationHud.resolve(context.participant(),context.geography()"));assertTrue(render.contains("FeatureClient.state().snapshot()"));assertTrue(render.contains("mc.player.getX(),mc.player.getZ()"));assertFalse(render.contains("featureMode()"));assertFalse(render.contains("xaero"));String pure=Files.readString(root.resolve("src/main/java/org/humanjourney/core/mapfeature/FeatureLocationHud.java"));assertFalse(pure.contains("net.minecraft.client"));assertFalse(pure.contains("FeatureCatalog"));assertFalse(pure.contains("GeographyClientConfig"));}
 @Test void pairMovesRightBelowCompassAndAwayFromTopCoordinateStrip(){var pair=BoundaryControlLayout.placePair(1000,600,List.of()).orElseThrow();assertEquals(880,pair.getFirst().x());assertEquals(108,pair.getFirst().y());assertTrue(pair.getFirst().x()>BoundaryControlLayout.place(1000,600,List.of()).orElseThrow().x());for(var r:pair){assertFalse(r.overlaps(BoundaryControlLayout.compass(1000,600)));assertFalse(r.overlaps(new BoundaryControlLayout.Rect(250,0,600,60)));}assertFalse(pair.get(0).overlaps(pair.get(1)));}
 @Test void occupiedRightEdgeFallsBackWithoutCoveringNativeWidget(){var occupied=new BoundaryControlLayout.Rect(874,108,118,44);var pair=BoundaryControlLayout.placePair(1000,600,List.of(occupied)).orElseThrow();for(var r:pair)assertFalse(r.overlaps(occupied));}
 @Test void noControlSpaceKeepsExistingSafeFailure(){assertTrue(BoundaryControlLayout.placePair(100,40,List.of()).isEmpty());assertTrue(BoundaryControlLayout.placePair(1000,600,List.of(new BoundaryControlLayout.Rect(0,0,1000,600))).isEmpty());}
}
